def radiusAndDiameter(n, roads):
    INF = 10 ** 15
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for a, b, w in roads:
        if w < d[a][b]:
            d[a][b] = d[b][a] = w
    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik < INF:
                d[i] = [x if x <= dik + y else dik + y for x, y in zip(d[i], dk)]
    ecc = [max(row) for row in d]
    if max(ecc) >= INF:
        return [-1, -1]
    return [min(ecc), max(ecc)]
